<?php
require_once 'config.php'; $page_title='College Fest Events';
$result=$conn->query("SELECT e.*, (SELECT COUNT(*) FROM registrations r WHERE r.event_id=e.id AND r.status='confirmed') AS registered FROM events e WHERE e.event_date >= CURDATE() ORDER BY e.event_date,e.event_time");
include 'includes/header.php'; ?>
<main><section class="hero"><div><p class="eyebrow">CAMPUS • COMMUNITY • COMPETITION</p><h1>Make your college fest <em>count.</em></h1><p class="hero-copy">Explore upcoming college events, reserve your place, and keep every registration organized from one dashboard.</p><a class="primary-btn" href="#events">Explore Events</a></div><div class="hero-card"><div class="hero-orbit"></div><span>EVENTHUB</span><strong>One place for every campus event.</strong></div></section>
<section class="section" id="events"><div class="section-heading"><div><p class="eyebrow">UPCOMING</p><h2>Find your next event</h2></div><span class="count-pill"><?= $result->num_rows ?> events</span></div><div class="event-grid">
